from lib import *
S = SS('l68')
steps = [
    step("用 ssh-keygen 生成 ed25519 密钥,设置 gpg.format = ssh、user.signingkey = alice.pub,git commit -S。commit 对象里多了 gpgsig 头:从 gpgsig -----BEGIN SSH SIGNATURE----- 开始,后面每行以一个空格开头续行(U1NIU0lHAAAA…是 base64 的签名),到 -----END SSH SIGNATURE----- 结束,然后才是空行和提交说明。签名放在提交对象里面,所以它是提交 hash 的一部分。", t=tl(S(1)), mark=lidx(S(1), '-----BEGIN SSH SIGNATURE-----', '-----END SSH SIGNATURE-----', 'gpg.format ssh'), done=lidx(S(1), 'user.signingkey', '签名的提交'), kv=KV([['gpg.format=ssh', '用 SSH 密钥签名'], ['user.signingkey', '公钥文件'], ['gpgsig 头', '签名在 commit 对象里']], ['gpgsig 头'])),
    step("验证需要告诉 git 信任谁:没配置 gpg.ssh.allowedSignersFile 时 git log --show-signature 输出 error: gpg.ssh.allowedSignersFile needs to be configured and exist for ssh signature verification 和 No signature。配置了一个只有一行“alice@example.com ssh-ed25519 AAAA…”的文件后,输出 Good \"git\" signature for alice@example.com with ED25519 key SHA256:…,指纹与 ssh-keygen -l 给出的公钥指纹一致(True)。", t=tl(S(2)), mark=lidx(S(2), 'needs to be configured', 'Good "git" signature for alice@example.com', '指纹与 ssh-keygen'), done=lidx(S(2), 'No signature', '配置 gpg.ssh.allowedSignersFile 之后'), kv=KV([['allowedSignersFile', '主体 + 公钥 的白名单'], ['没有配置', 'No signature(无法验证)'], ['Good', '签名有效且签名者在白名单里']], ['allowedSignersFile'])),
    step("手工验证:取出 commit 对象,去掉 gpgsig 头,剩下的内容就是被签名的内容;用 ssh-keygen -Y verify -n git(命名空间 git)验证,输出 Good \"git\" signature for alice@example.com,退出码 0,和 git 一致。把说明改一个字再验证,Signature verification failed: incorrect signature,退出码 255;命名空间换成 other,Couldn't verify signature: namespace does not match——SSH 签名带命名空间,git 提交的签名不能被当作别的用途的签名。", t=tl(S(3)), mark=lidx(S(3), '改一个字之后再验证', 'namespace does not match'), done=lidx(S(3), 'ssh-keygen -Y verify:', '退出码 0'), kv=KV([['被签名的内容', 'commit 对象去掉 gpgsig 头'], ['命名空间', 'git,防止跨用途重放'], ['改一个字', '验证失败']], ['命名空间'])),
    step("篡改提交:把说明改一个字、保留原来的 gpgsig 头,用 git hash-object -t commit -w 写成新对象。git verify-commit 输出 Could not verify signature. 和 Signature verification failed: incorrect signature,退出码 1。签名绑定了提交的全部内容(tree、parent、作者、说明),动任何一个字节都会失败。", t=tl(S(4)), mark=lidx(S(4), 'incorrect signature', '退出码 1'), done=lidx(S(4), 'git verify-commit'), kv=KV([['签名覆盖', 'tree、parent、author、说明…'], ['篡改', '验证失败,退出码 1']], ['签名覆盖'])),
    step("不在白名单里的签名者:用 mallory 的密钥签名,git log --show-signature 输出 Good \"git\" signature with ED25519 key SHA256:…(注意没有 “for 主体”)和 No principal matched.——签名本身有效,但这个公钥没有对应的主体,不受信任。白名单行加上 valid-before=\"20200101\" 之后,alice 再签一次的提交:key has expired: verify time 2026-01-01T… > valid-before 2020-01-01,No principal matched.——公钥过期也不被信任。", t=tl(S(5)), mark=lidx(S(5), 'No principal matched', 'key has expired'), done=lidx(S(5), 'Good "git" signature with ED25519', '陌生人签名的提交', 'alice 再签一次'), kv=KV([['No principal matched', '签名有效但签名者不在白名单'], ['valid-before', '白名单条目可以设有效期'], ['过期', '同样不受信']], ['No principal matched'])),
    step("git log --format='%G? %GS' 一行看出每个提交的签名状态:G(好签名且受信,主体 alice@example.com)、U(签名有效但不受信:陌生人签名的提交)、N(没有签名:没签名的提交)。git tag -s 同样可以签标签,git tag -v v1 输出 Good \"git\" signature for alice@example.com,标签对象里有 1 个 SSH 签名块。其它状态:B 坏签名、E 无法检查(这里没有出现)。", t=tl(S(6)), mark=lidx(S(6), 'N    没签名的提交', 'U    陌生人签名的提交', 'G  alice@example.com'), done=lidx(S(6), '标签对象里的签名块个数: 1'), kv=KV([['G', '好签名 + 受信'], ['U', '好签名 + 不受信'], ['N', '没有签名'], ['B / E', '坏签名 / 无法检查']], ['G'])),
]
A = mkarti('l68', 68, 'Git,SSH 签名,gpg.format,allowed_signers,真实验证,动画演示',
    '实测 SSH 签名提交:gpg.format=ssh 与 user.signingkey 签出带 gpgsig 头(-----BEGIN SSH SIGNATURE-----)的 commit;验证要配置 gpg.ssh.allowedSignersFile,否则 No signature;手工去掉 gpgsig 头后用 ssh-keygen -Y verify -n git 验证与 git 一致,改一个字或换命名空间都失败;篡改提交验证失败;陌生人签名显示 No principal matched,白名单可设 valid-before 过期;%G? 状态码 G/U/N;签名标签。',
    '用 SSH 密钥给提交签名,比 GPG 轻便得多。这篇看签名在 commit 对象里长什么样、怎样在本地验证、怎样配置“信任谁”,以及篡改、陌生人签名、密钥过期时各自会怎么显示。',
    [('gpgsig', 'commit 对象里放 SSH 签名的头,从 BEGIN SSH SIGNATURE 到 END SSH SIGNATURE'), ('No principal matched', '签名有效但公钥不在 allowed_signers 里时的提示'), ('G / U / N', '%G? 状态码:好且受信 / 好但不受信 / 没有签名')],
    [('签名在哪', '<p>设置 <code>gpg.format=ssh</code> 和 <code>user.signingkey</code>(公钥文件),<code>git commit -S</code> 之后,commit 对象里多一个 <code>gpgsig</code> 头,里面是 SSH 签名的文本形式。签名是提交内容(去掉 gpgsig 头)的签名,命名空间是 <code>git</code>。</p>'),
     ('信任谁', '<p>git 需要 <code>gpg.ssh.allowedSignersFile</code>:每行“主体 [选项] 公钥”。没有它就无法验证(<code>No signature</code>)。公钥在白名单里才算 Good for 某主体;不在就是 <code>No principal matched</code>;白名单条目可带 <code>valid-before</code> 等选项。</p>'),
     ('手工验证', '<p>去掉 gpgsig 头的 commit 内容用 <code>ssh-keygen -Y verify -n git</code> 验证,结果与 git 一致;改一个字符、换命名空间都会失败。</p>'),
     ('篡改', '<p>签名覆盖提交的全部内容,保留原来的 gpgsig 头而改动说明得到的新对象,<code>git verify-commit</code> 报 <code>incorrect signature</code>。</p>'),
     ('陌生人与过期', '<p>公钥不在白名单里:签名本身有效,git 显示 <code>Good "git" signature with ED25519 key …</code> 但接着 <code>No principal matched</code>;白名单条目带 <code>valid-before</code> 且已过期时同样不受信,并说明 <code>key has expired</code>。</p>'),
     ('状态码', '<p><code>%G?</code>:G 好签名且受信,U 好签名但不受信,B 坏签名,N 没有签名,E 无法检查。标签用 <code>git tag -s</code> 签名,<code>git tag -v</code> 验证。</p>')],
    steps,
    [ENV_I_GIT + '。密钥用 ssh-keygen 生成 ed25519(无口令),保存在实验目录里反复使用以便指纹稳定;所有验证都是本机离线完成;输出里指纹做了替换;验证时间显示的 “2026-01-01” 来自固定的提交时间',
     '没有验证:GitHub 等平台对 SSH 签名的 “Verified” 显示;ssh-agent 与硬件密钥(FIDO);RSA/ECDSA 密钥;allowed_signers 里的 cert-authority、namespaces 选项;吊销列表;git log --show-signature 在合并提交上的行为;GPG 签名与 SSH 签名的混用'],
    'SSH 签名')
